<?php
/**
 * login.php — TMS AI Travel Copilot
 *
 * ROOT-CAUSE FIX (audit finding): this page's own <form> used to require a
 * bespoke `login_token` hidden field, generated by THIS file. The site-wide
 * "Sign In" modal (includes/header.php, opened from the topbar on every
 * page) posts to this same script but never included that field and used
 * different field names (email/password instead of EmailId/Password) — so
 * the modal every visitor actually sees could never successfully log in;
 * it always fell into the "Session expired" branch. Both entry points now
 * use the same project-wide CSRF helper (tms_csrf_field()/tms_csrf_validate())
 * and the same field names, so either form works correctly.
 */
require_once 'includes/config.php';

// Already logged in
if (!empty($_SESSION['login'])) {
    header('Location: index.php');
    exit;
}

$error = '';

if ($_SERVER['REQUEST_METHOD'] === 'POST') {
    tms_csrf_validate();

    // Accept both the standalone page's field names (EmailId/Password) and
    // the topbar modal's (email/password), so either source works.
    $email    = filter_var(trim($_POST['EmailId'] ?? $_POST['email'] ?? ''), FILTER_VALIDATE_EMAIL);
    $password = $_POST['Password'] ?? $_POST['password'] ?? '';
    $ip       = $_SERVER['REMOTE_ADDR'] ?? 'unknown';

    if (!$email || empty($password)) {
        $error = 'Please enter your email and password.';
    } else {
        // FIX (Round 14): the brute-force lockout was implemented and recorded
        // (tms_record_failed_login below) but NEVER checked here — the only
        // caller of tms_login_lockout_minutes_remaining() was admin/index.php.
        // tbl_login_attempts filled up with rows nothing ever read, and customer
        // accounts accepted unlimited password guesses.
        $waitMinutes = tms_login_lockout_minutes_remaining($dbh, $email, $ip);
        if ($waitMinutes > 0) {
            $error = "Too many failed sign-in attempts. Please try again in {$waitMinutes} minute"
                   . ($waitMinutes === 1 ? '' : 's') . '.';
            $user = null;
        } else {
            $stmt = $dbh->prepare("SELECT id, FullName, Password FROM tblusers WHERE EmailId = ? LIMIT 1");
            $stmt->execute([$email]);
            $user = $stmt->fetch(PDO::FETCH_OBJ);
        }

        // FIX (Round 14): this called password_verify() directly, so every
        // account still holding a legacy md5 hash — including the seeded demo
        // users — could never sign in on the website, even though the SAME
        // credentials worked through api/index.php. Every other login path in
        // the app (admin, API, change-password, 2FA) uses this shared helper,
        // which accepts a legacy hash and transparently upgrades it to bcrypt.
        if ($user && tms_verify_password($password, $user->Password, (int)$user->id, $dbh)) {
            tms_clear_login_attempts($dbh, $email, $ip);
            // SECURITY FIX (Section 13 audit): admin/index.php already
            // regenerates the session ID on successful login to prevent
            // session fixation (an attacker who gets a victim to use a
            // session ID the attacker already knows — e.g. via a link
            // with a pre-set session cookie — can otherwise just wait
            // for the victim to log in and inherit their authenticated
            // session). Customer login never did this at all.
            session_regenerate_id(true);
            $_SESSION['login']    = $email;
            $_SESSION['userid']   = $user->id;
            $_SESSION['username'] = $user->FullName;
            $redirect = $_POST['redirect'] ?? '';
            if (!empty($_SESSION['post_login_redirect'])) {
                $redirect = $_SESSION['post_login_redirect'];
                unset($_SESSION['post_login_redirect']);
            }
            // Allow same-site paths (including the leading "/tms/..." this
            // app is hosted under) but block open-redirect vectors: a
            // protocol-relative URL ("//evil.com") or any absolute URL
            // ("https://evil.com").
            $safeRedirect = (is_string($redirect) && $redirect !== ''
                    && !str_starts_with($redirect, '//') && !str_contains($redirect, '://'))
                ? $redirect : 'index.php';
            header('Location: ' . $safeRedirect);
            exit;
        } else {
            tms_record_failed_login($dbh, $email, $ip);
            $error = 'Invalid email or password. Please try again.';
        }
    }
}
